def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(v == c for row in grid for v in row))

    # Fill rectangular outlines, using color 2 for a 2x2 interior and 7 otherwise.
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    color = grid[r1][c1]
                    if color == bg:
                        continue
                    if (all(grid[r1][c] == color and grid[r2][c] == color for c in range(c1, c2 + 1))
                        and all(grid[r][c1] == color and grid[r][c2] == color for r in range(r1, r2 + 1))
                        and all(grid[r][c] == bg for r in range(r1 + 1, r2) for c in range(c1 + 1, c2))):
                        fill = 2 if (r2-r1-1 == 2 and c2-c1-1 == 2) else 7
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                out[r][c] = fill

    # Recolor the center of 3x3 solid-color motifs with a background center.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == bg:
                continue
            if all(grid[r+i][c+j] == color for i in range(3) for j in range(3) if (i, j) != (1, 1)) and grid[r+1][c+1] == bg:
                out[r+1][c+1] = 7
    return out
